verus! {
    use verus::prelude::*;

    /// Given a vector of characters `s`, returns the vector of all non‐empty
    /// prefixes of `s` in order.
    ///
    /// If `s` has length `n`, the result has length `n`, and for each
    /// `0 <= i < n`, result[i].len() == i+1 and
    /// result[i][j] == s[j] for all `0 <= j < i+1`.
    pub fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>>
        ensures |res: &Vec<Vec<char>>|
            // result has same length as input
            res.len() == s.len()
            // each prefix i has length i+1 and matches s[0..=i]
            && forall(|i: usize| i < s.len() ==>
                res.index(i).len() == i + 1
                && forall(|j: usize| j < res.index(i).len() ==>
                    res.index(i)[j] == s.index(j)
                )
            )
    {
        let mut res = Vec::<Vec<char>>::new();
        let mut i: usize = 0;
        // build prefixes of length 1, 2, …, s.len()
        while i < s.len() {
            invariant i <= s.len();
            invariant res.len() == i;
            invariant forall(|j: usize| j < i ==>
                // already built correct prefixes for all j < i
                res.index(j).len() == j + 1
                && forall(|k: usize| k < res.index(j).len() ==>
                    res.index(j)[k] == s.index(k)
                )
            );
            // measure for termination: s.len() - i decreases each iteration
            decreases s.len() - i;

            // now build the (i+1)-length prefix
            let mut prefix = Vec::<char>::new();
            let mut k: usize = 0;
            while k <= i {
                invariant k <= i + 1;
                invariant prefix.len() == k;
                invariant forall(|j: usize| j < k ==> prefix.index(j) == s.index(j));
                // measure for termination: (i+1) - k decreases each iteration
                decreases i + 1 - k;

                prefix.push(s.index(k));
                k += 1;
            }

            // append the newly built prefix of length i+1
            res.push(prefix);
            i += 1;
        }

        res
    }
}